{"role":"assistant","content":[{"type":"text","text":"现在是检索客户端（ES + KG）："},{"type":"tool-call","toolCallId":"call_69c125bd2b2947dcacf6244c","toolName":"write_to_file","args":{"filePath":"c:/Ming/cuda/smart-QnA/app/retrieval/es_client.py","content":""""Elasticsearch 交互逻辑。

针对 `article` 与 `qna` 两个索引提供关键字检索（BM25），
返回统一结构的命中结果。使用官方 async client。
"""

from __future__ import annotations

from typing import Any, Optional

from app.core.exceptions import ESConnectionError, RetrievalError
from app.schemas.responses import SourceItem

# 不同索引的字段映射：默认检索 content 字段，title 用于展示。
_INDEX_FIELDS = {
    "article": {"body": "content", "title": "title"},
    "qna": {"body": "answer", "title": "question"},
}


class ESClient:
    """Elasticsearch 异步客户端封装。"""

    def __init__(self, es_config: dict):
        self.url = es_config.get("url", "http://localhost:9200")
        self.username = es_config.get("username", "")
        self.password = es_config.get("password", "")
        self.article_index = es_config.get("article_index", "article")
        self.qna_index = es_config.get("qna_index", "qna")
        self.verify_certs = bool(es_config.get("verify_certs", False))
        self._client: Any = None

    # ------------------------------------------------------------------ #
    @property
    def client(self):
        if self._client is None:
            try:
                from elasticsearch import AsyncElasticsearch
            except ImportError as exc:  # pragma: no cover
                raise RetrievalError("未安装 elasticsearch 依赖") from exc
            kwargs: dict = {"hosts": [self.url]}
            if self.username:
                kwargs["basic_auth"] = (self.username, self.password)
            kwargs["verify_certs"] = self.verify_certs
            self._client = AsyncElasticsearch(**kwargs)
        return self._client

    def reconfigure(self, es_config: dict) -> None:
        self.url = es_config.get("url", "http://localhost:9200")
        self.username = es_config.get("username", "")
        self.password = es_config.get("password", "")
        self.article_index = es_config.get("article_index", "article")
        self.qna_index = es_config.get("qna_index", "qna")
        self.verify_certs = bool(es_config.get("verify_certs", False))
        self._client = None

    async def close(self) -> None:
        if self._client is not None:
            try:
                await self._client.close()
            except Exception:  # noqa: BLE001
                pass
            self._client = None

    # ------------------------------------------------------------------ #
    async def search_article(self, query: str, top_k: int = 5) -> list[SourceItem]:
        return await self._search(self.article_index, "article", query, top_k)

    async def search_qna(self, query: str, top_k: int = 5) -> list[SourceItem]:
        return await self._search(self.qna_index, "qna", query, top_k)

    async def _search(
        self, index: str, source_type: str, query: str, top_k: int
    ) -> list[SourceItem]:
        fields = _INDEX_FIELDS.get(source_type, {"body": "content", "title": "title"})
        body = {
            "size": top_k,
            "query": {
                "multi_match": {
                    "query": query,
                    "fields": [f"{fields['body']}^3", fields["title"]],
                    "type": "best_fields",
                }
            },
        }
        try:
            resp = await self.client.search(index=index, body=body)
        except Exception as exc:  # noqa: BLE001
            raise ESConnectionError(f"Elasticsearch 检索失败 ({index}): {exc}") from exc

        items: list[SourceItem] = []
        hits = resp.get("hits", {}).get("hits", [])
        for hit in hits:
            src = hit.get("_source", {}) or {}
            items.append(
                SourceItem(
                    source=source_type,
                    title=src.get(fields["title"]) or src.get("title"),
                    content=str(src.get(fields["body"], "")),
                    score=hit.get("_score"),
                    meta={"_id": hit.get("_id"), "index": index},
                )
            )
        return items
"}}]}

{"role":"assistant","content":[{"type":"text","text":"-"},{"type":"tool-call","toolCallId":"call_24bb2632341b433db4f42017","toolName":"write_to_file","args":{"filePath":"c:/Ming/cuda/smart-QnA/app/api/dependencies.py","content":""""依赖注入：构造并复用单例服务组件。

通过 `lru_cache` 在应用生命周期内复用同一组客户端实例，
当配置更新时调用 `reconfigure_*` 刷新内部连接。
"""

from __future__ import annotations

from functools import lru_cache
from typing import Optional

from app.core.config_manager import ConfigManager
from app.core.exceptions import ConfigNotFoundError
from app.core.llm_client import LLMClient
from app.retrieval.es_client import ESClient
from app.retrieval.kg_client import KGClient
from app.retrieval.orchestrator import Orchestrator

# 全局配置管理器实例（延迟创建，便于测试覆盖）。
_config_manager: Optional[ConfigManager] = None


def get_config_manager() -> ConfigManager:
    global _config_manager
    if _config_manager is None:
        _config_manager = ConfigManager()
    return _config_manager


def set_config_manager(manager: ConfigManager) -> None:
    """测试用：注入自定义配置管理器。"""
    global _config_manager
    _config_manager = manager


@lru_cache(maxsize=1)
def get_llm_client() -> LLMClient:
    cfg = get_config_manager().get_section("llm")
    return LLMClient(cfg)


@lru_cache(maxsize=1)
def get_es_client() -> ESClient:
    cfg = get_config_manager().get_section("elasticsearch")
    return ESClient(cfg)


@lru_cache(maxsize=1)
def get_kg_client() -> KGClient:
    cfg = get_config_manager().get_section("neo4j")
    return KGClient(cfg)


@lru_cache(maxsize=1)
def get_orchestrator() -> Orchestrator:
    return Orchestrator(get_llm_client(), get_es_client(), get_kg_client())


def rebuild_clients() -> None:
    """配置更新后重建各客户端（清空 lru_cache 并按新配置重建）。"""
    get_llm_client.cache_clear()
    get_es_client.cache_clear()
    get_kg_client.cache_clear()
    get_orchestrator.cache_clear()
    # 触发重建
    get_orchestrator()
