.msg.assistant { align-self: flex-start; background: var(--panel); border: 1px solid var(--border); }
.msg.system { align-self: center; background: transparent; color: var(--muted); font-size: 13px; max-width: 100%; }
.msg.error { align-self: center; background: rgba(239,68,68,.15); border: 1px solid var(--err); color: #fecaca; }

.composer {
  display: flex;
  gap: 10px;
  padding: 14px 20px;
  border-top: 1px solid var(--border);
  background: var(--panel);
}
.composer textarea {
  flex: 1;
  resize: none;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  padding: 10px 12px;
  font-size: 14px;
}

.chat-side {
  width: 280px;
  border-left: 1px solid var(--border);
  background: var(--panel);
  padding: 18px;
  overflow-y: auto;
}
.chat-side h3 { margin: 14px 0 8px; font-size: 14px; color: var(--muted); }
.chat-side label { display: block; margin-bottom: 12px; font-size: 13px; }
.chat-side input, .chat-side select {
  width: 100%;
  margin-top: 4px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  padding: 6px 8px;
  font-size: 13px;
}
.checkbox { display: flex !important; align-items: center; gap: 6px; }
.checkbox input { width: auto; margin: 0 !important; }
.source-list { font-size: 12px; color: var(--muted); max-height: 320px; overflow-y: auto; }
.source-list .item { padding: 6px 0; border-bottom: 1px dashed var(--border); }

/* ============ 按钮 ============ */
button {
  cursor: pointer;
  border: none;
  border-radius: 8px;
  padding: 9px 18px;
  font-size: 14px;
  font-weight: 500;
}
.primary { background: var(--primary); color: #fff; }
.primary:hover { background: var(--primary-hover); }
.ghost { background: transparent; color: var(--muted); border: 1px solid var(--border); }
.ghost:hover { color: var(--text); }
button:disabled { opacity: .5; cursor: not-allowed; }

/* ============ 配置 ============ */
.config-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
}
.config-bar .hint { font-size: 12px; color: var(--muted); }
.config-form {
  padding: 20px;
  overflow-y: auto;
  height: calc(100% - 60px);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 18px;
}
fieldset {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  background: var(--panel);
}
legend { padding: 0 8px; color: var(--muted); font-size: 13px; }
.config-form label { display: block; margin-bottom: 10px; font-size: 13px; color: var(--muted); }
.config-form input {
  width: 100%;
  margin-top: 4px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  padding: 7px 9px;
  font-size: 13px;
}
.config-form .checkbox { display: flex; align-items: center; gap: 6px; color: var(--text); }
.config-form .checkbox input { width: auto; margin: 0; }
