敏感字段（api_key / password）在落盘时以 Base64 编码存储，
读取时自动解码供内部使用。对外暴露的配置快照会将敏感字段脱敏。
"""

from __future__ import annotations

import base64
import json
import os
import threading
from copy import deepcopy
from pathlib import Path
from typing import Any, Optional

from app.core.exceptions import ConfigError, ConfigNotFoundError

# 标记为敏感的字段路径（使用点号分隔），落盘时 Base64 编码。
SENSITIVE_FIELDS: tuple[tuple[str, ...], ...] = (
    ("llm", "api_key"),
    ("elasticsearch", "password"),
    ("neo4j", "password"),
)

# 默认配置文件路径（相对项目根）。
DEFAULT_CONFIG_PATH = Path(__file__).resolve().parent.parent.parent / "data" / "config.json"


# 编码后敏感字段的前缀，用于区分「已编码」与「明文」。
# 这样手动编辑 config.json 填写的明文 api_key 不会被误当作 Base64 解码。
_B64_PREFIX = "b64:"


def _b64encode(value: str) -> str:
    if not value:
        return ""
    # 已编码则原样返回，避免重复编码
    if value.startswith(_B64_PREFIX):
        return value
    return _B64_PREFIX + base64.b64encode(value.encode("utf-8")).decode("ascii")


def _b64decode(value: str) -> str:
    """解码敏感字段。

    仅对带 `b64:` 前缀的值解码；无前缀则视为明文原样返回，
    这样用户手动编辑配置文件填写的明文密钥也能正常使用。
    """
    if not value:
        return ""
    if not value.startswith(_B64_PREFIX):
        return value  # 明文，直接使用
    raw = value[len(_B64_PREFIX):]
    try:
        return base64.b64decode(raw.encode("ascii")).decode("utf-8")
    except Exception as exc:  # noqa: BLE001
        raise ConfigError(f"配置字段 Base64 解码失败: {exc}") from exc


def _get_nested(data: dict, path: tuple[str, ...]) -> Any:
    cur = data
    for key in path:
        if not isinstance(cur, dict) or key not in cur:
            return None
        cur = cur[key]
    return cur


def _set_nested(data: dict, path: tuple[str, ...], value: Any) -> None:
    cur = data
    for key in path[:-1]:
        cur = cur.setdefault(key, {})
    cur[path[-1]] = value


class ConfigManager:
    """线程安全的配置管理器。

    内部缓存一份明文配置（敏感字段已解码）；每次写操作都会同步落盘。
    """

    def __init__(self, config_path: Optional[Path | str] = None):
        self.config_path = Path(config_path) if config_path else DEFAULT_CONFIG_PATH
        self._lock = threading.RLock()
        self._config: dict = {}
        self.reload()

    # ------------------------------------------------------------------ #
    # 读写
    # ------------------------------------------------------------------ #
    def reload(self) -> dict:
        """从磁盘重新加载配置并解码敏感字段。"""
        with self._lock:
            if not self.config_path.exists():
                raise ConfigNotFoundError(f"配置文件不存在: {self.config_path}")
            try:
                raw = json.loads(self.config_path.read_text(encoding="utf-8"))
            except json.JSONDecodeError as exc:
                raise ConfigError(f"配置文件 JSON 解析失败: {exc}") from exc
            if not isinstance(raw, dict):
                raise ConfigError("配置文件根必须是 JSON 对象")
            # 解码敏感字段
            decoded = deepcopy(raw)
            for path in SENSITIVE_FIELDS:
                val = _get_nested(decoded, path)
                if isinstance(val, str) and val:
                    _set_nested(decoded, path, _b64decode(val))
            self._config = decoded
            return deepcopy(self._config)

    def save(self, config: dict) -> None:
        """将配置写入磁盘（敏感字段 Base64 编码）。"""
        with self._lock:
            if not isinstance(config, dict):
                raise ConfigError("配置必须是 JSON 对象")
            encoded = deepcopy(config)
            for path in SENSITIVE_FIELDS:
                val = _get_nested(encoded, path)
                if isinstance(val, str) and val:
                    _set_nested(encoded, path, _b64encode(val))
            self.config_path.parent.mkdir(parents=True, exist_ok=True)
            tmp = self.config_path.with_suffix(".json.tmp")
            tmp.write_text(json.dumps(encoded, indent=2, ensure_ascii=False), encoding="utf-8")
            os.replace(tmp, self.config_path)
            # 重新加载以刷新内部缓存
            self._config = self._decode_into_memory(encoded)

    def _decode_into_memory(self, encoded: dict) -> dict:
        decoded = deepcopy(encoded)
        for path in SENSITIVE_FIELDS:
            val = _get_nested(decoded, path)
            if isinstance(val, str) and val:
                _set_nested(decoded, path, _b64decode(val))
        return decoded

    # ------------------------------------------------------------------ #
    # 访问
    # ------------------------------------------------------------------ #
    def get(self) -> dict:
        """返回内部明文配置的深拷贝。"""
        with self._lock:
            return deepcopy(self._config)

    def get_section(self, section: str) -> dict:
        with self._lock:
            value = self._config.get(section)
            if value is None:
                raise ConfigNotFoundError(f"配置段不存在: {section}")
            return deepcopy(value)

    def update(self, partial: dict) -> dict:
        """深度合并部分配置并落盘，返回更新后的完整明文配置。"""
        with self._lock:
            merged = deepcopy(self._config)
            _deep_merge(merged, partial)
            self.save(merged)
            return deepcopy(self._config)

    def masked(self) -> dict:
        """返回敏感字段已脱敏的配置快照，用于对外展示。"""
        with self._lock:
            snapshot = deepcopy(self._config)
            for path in SENSITIVE_FIELDS:
                val = _get_nested(snapshot, path)
                if isinstance(val, str) and val:
                    _set_nested(snapshot, path, _mask(val))
            return snapshot


def _mask(value: str) -> str:
    if not value:
        return ""
    if len(value) <= 4:
        return "****"
    return value[:2] + "*" * (len(value) - 4) + value[-2:]


def _deep_merge(base: dict, override: dict) -> dict:
    """递归合并 override 到 base（就地修改 base）。"""
    for key, val in override.items():
        if key in base and isinstance(base[key], dict) and isinstance(val, dict):
            _deep_merge(base[key], val)
        else:
            base[key] = val
    return base
