(function () {
  "use strict";

  const $ = (sel) => document.querySelector(sel);

  // -------------------- 标签切换 --------------------
  document.querySelectorAll(".tab").forEach((tab) => {
    tab.addEventListener("click", () => {
      document.querySelectorAll(".tab").forEach((t) => t.classList.remove("active"));
      tab.classList.add("active");
      const target = tab.dataset.tab;
      document.querySelectorAll(".panel").forEach((p) => p.classList.remove("active"));
      $("#tab-" + target).classList.add("active");
    });
  });

  // -------------------- 健康检查 --------------------
  async function checkHealth() {
    const dot = $("#healthDot");
    const text = $("#healthText");
    try {
      const resp = await fetch("/api/health");
      if (!resp.ok) throw new Error("bad status");
      dot.className = "dot ok";
      text.textContent = "服务正常";
    } catch (e) {
      dot.className = "dot err";
      text.textContent = "服务不可用";
    }
  }
  checkHealth();
  setInterval(checkHealth, 30000);

  // -------------------- 问答测试 --------------------
  const messages = $("#messages");
  const queryInput = $("#queryInput");
  const sendBtn = $("#sendBtn");
  const clearBtn = $("#clearBtn");
  const sourceList = $("#sourceList");

  function addMsg(role, text) {
    const div = document.createElement("div");
    div.className = "msg " + role;
    div.textContent = text;
    messages.appendChild(div);
    messages.scrollTop = messages.scrollHeight;
    return div;
  }

  function renderSources(sources) {
    if (!sources || !sources.length) {
      sourceList.textContent = "—";
      return;
    }
    sourceList.innerHTML = sources
      .map(
        (s, i) =>
          `<div class="item">[${i + 1}] <b>${esc(s.source)}</b>` +
          (s.title ? " · " + esc(s.title) : "") +
          (s.score ? " (" + Number(s.score).toFixed(2) + ")" : "") +
          `</div>`
      )
      .join("");
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])
    );
  }

  function renderApiUrl(url) {
    const el = $("#apiUrl");
    if (!url) {
      el.textContent = "—";
      return;
    }
    el.innerHTML = '<a href="' + esc(url) + '" target="_blank" rel="noopener">' + esc(url) + "</a>";
  }

  sendBtn.addEventListener("click", async () => {
    const query = queryInput.value.trim();
    if (!query) return;
    const mode = $("#modeSelect").value;
    const top_k = parseInt($("#topkInput").value, 10) || 5;
    const stream = $("#streamCheck").checked;

    addMsg("user", query);
    queryInput.value = "";
    sendBtn.disabled = true;
    sourceList.textContent = "检索中…";
    renderApiUrl(null);

    if (stream) {
      await streamChat(query, mode, top_k);
    } else {
      await blockingChat(query, mode, top_k);
    }
    sendBtn.disabled = false;
  });

  clearBtn.addEventListener("click", () => {
    messages.innerHTML = "";
    sourceList.textContent = "—";
  });

  queryInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendBtn.click();
    }
  });

  // 流式（SSE）
  async function streamChat(query, mode, top_k) {
    const assistant = addMsg("assistant", "");
    let buf = "";
    let pending = "";

    const resp = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "text/event-stream" },
      body: JSON.stringify({ query, mode: mode || null, top_k, stream: true }),
    });

    if (!resp.ok || !resp.body) {
      addMsg("error", "请求失败：" + resp.status);
      return;
    }

    const reader = resp.body.getReader();
    const decoder = new TextDecoder();

    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      pending += decoder.decode(value, { stream: true });
      const blocks = pending.split("\n\n");
      pending = blocks.pop();
      for (const block of blocks) {
        handleEvent(block, {
          onMeta: (data) => {
            renderSources(data.sources);
            renderApiUrl(data.api_url);
          },
          onToken: (data) => {
            buf += data.content;
            assistant.textContent = buf;
            messages.scrollTop = messages.scrollHeight;
          },
          onError: (data) => addMsg("error", "错误：" + (data.error?.message || "未知")),
          onDone: () => {
            if (!buf) assistant.textContent = "(空回复)";
          },
        });
      }
    }
  }

  function handleEvent(block, cbs) {
    let event = "message";
    let dataStr = "";
    for (const line of block.split("\n")) {
      if (line.startsWith("event:")) event = line.slice(6).trim();
      else if (line.startsWith("data:")) dataStr += line.slice(5).trim();
    }
    if (!dataStr) return;
    let data = {};
    try { data = JSON.parse(dataStr); } catch (e) { return; }
    if (event === "meta") cbs.onMeta(data);
    else if (event === "token") cbs.onToken(data);
    else if (event === "error") cbs.onError(data);
    else if (event === "done") cbs.onDone(data);
  }

  // 非流式
  async function blockingChat(query, mode, top_k) {
    const assistant = addMsg("assistant", "思考中…");
    try {
      const resp = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query, mode: mode || null, top_k, stream: false }),
      });
      const data = await resp.json();
      if (!resp.ok) {
        assistant.className = "msg error";
        assistant.textContent = "错误：" + (data.error?.message || resp.status);
        return;
      }
      assistant.textContent = data.answer || "(空回复)";
      renderSources(data.sources);
      renderApiUrl(data.api_url);
    } catch (e) {
      assistant.className = "msg error";
      assistant.textContent = "请求异常：" + e.message;
    }
  }

  // -------------------- 配置管理 --------------------
  const configForm = $("#configForm");

  $("#loadConfigBtn").addEventListener("click", loadConfig);
  $("#saveConfigBtn").addEventListener("click", saveConfig);

  async function loadConfig() {
    try {
      const resp = await fetch("/api/config");
      const data = await resp.json();
      if (!resp.ok) {
        alert("加载失败：" + (data.error?.message || resp.status));
        return;
      }
      fillForm(data);
      alert("配置已加载");
    } catch (e) {
      alert("加载异常：" + e.message);
    }
  }

  function fillForm(data) {
    configForm.querySelectorAll("input").forEach((i) => {
      if (i.type === "checkbox") i.checked = false;
      else i.value = "";
    });
    setVal("llm.api_base", data.llm?.api_base);
    setVal("llm.api_key", data.llm?.api_key);
    setVal("llm.model", data.llm?.model);
    setVal("llm.entity_model", data.llm?.entity_model);
    setVal("llm.temperature", data.llm?.temperature);
    setVal("llm.max_tokens", data.llm?.max_tokens);
    setVal("elasticsearch.url", data.elasticsearch?.url);
    setVal("elasticsearch.username", data.elasticsearch?.username);
    setVal("elasticsearch.password", data.elasticsearch?.password);
    setVal("elasticsearch.article_index", data.elasticsearch?.article_index);
    setVal("elasticsearch.qna_index", data.elasticsearch?.qna_index);
    setCheck("elasticsearch.verify_certs", data.elasticsearch?.verify_certs);
    setVal("neo4j.uri", data.neo4j?.uri);
    setVal("neo4j.username", data.neo4j?.username);
    setVal("neo4j.password", data.neo4j?.password);
    setVal("server.host", data.server?.host);
    setVal("server.port", data.server?.port);
  }

  function setVal(name, value) {
    const el = configForm.querySelector(`[name="${name}"]`);
    if (el && value !== undefined && value !== null) el.value = value;
  }
  function setCheck(name, value) {
    const el = configForm.querySelector(`[name="${name}"]`);
    if (el) el.checked = !!value;
  }

  async function saveConfig() {
    const payload = {};
    configForm.querySelectorAll("input").forEach((el) => {
      const name = el.getAttribute("name");
      if (!name) return;
      // 留空的敏感字段不提交（避免清空已有值）
      if (el.type === "text") {
        if (el.value === "" && isSensitive(name)) return;
        setNested(payload, name, el.value);
      } else if (el.type === "number") {
        if (el.value === "") return;
        setNested(payload, name, Number(el.value));
      } else if (el.type === "checkbox") {
        setNested(payload, name, el.checked);
      }
    });
    try {
      const resp = await fetch("/api/config", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await resp.json();
      if (!resp.ok) {
        alert("保存失败：" + (data.detail?.error?.message || data.error?.message || resp.status));
        return;
      }
      alert("配置已保存");
    } catch (e) {
      alert("保存异常：" + e.message);
    }
  }

  function isSensitive(name) {
    return ["llm.api_key", "elasticsearch.password", "neo4j.password"].includes(name);
  }

  function setNested(obj, path, value) {
    const keys = path.split(".");
    let cur = obj;
    for (let i = 0; i < keys.length - 1; i++) {
      cur[keys[i]] = cur[keys[i]] || {};
      cur = cur[keys[i]];
    }
    cur[keys[keys.length - 1]] = value;
  }
})();
