        async with measure("embedding", "embed") as m:
            try:
                resp = await self.client.embeddings.create(
                    model=self.model,
                    input=text,
                )
                m["tokens"] = resp.usage.total_tokens if resp.usage else 0
                return resp.data[0].embedding
