        if not self.configured:
            return {"ok": False, "message": "embedding 未完整配置（缺 api_key/model）"}
        try:
            vec = await self.embed("ping")
            return {"ok": True, "message": f"embedding 可用: {self.model} (dim={len(vec)})"}
