def _apply_to_sensitive(config: dict, fn) -> None:
    for section, sensitive_keys in ITEM_SECTIONS.items():
        sec = config.get(section)
        if not isinstance(sec, dict):
            continue
        items = sec.get("items")
        if not isinstance(items, dict):
            continue
        for item in items.values():
